/* 사케 카드 — 앱 로직.
   도감(catalog.json)은 읽기 전용, 내 컬렉션과 노트는 localStorage.
   서버 없이 각자 브라우저에 남는다. */
(function(){
'use strict';
var K_MINE='sake.mine.v1', K_NOTE='sake.note.v1';
var AX=[['華やか','화려함'],['芳醇','풍부함'],['重厚','묵직함'],['穏やか','부드러움'],['ドライ','드라이'],['軽快','가벼움']];
var TAGS=[['酸味','산미'],['辛口','드라이'],['旨味','감칠맛'],['フルーティ','과일향'],['スッキリ','깔끔'],
          ['しっかり','묵직'],['甘味','단맛'],['穀物','곡물향'],['苦味','쓴맛'],['コク','바디감'],
          ['バランス','균형'],['さっぱり','산뜻'],['ほのか','은은'],['キレ','끝맛']];
var TEMPS=[['雪冷え','유키비에 5℃'],['花冷え','하나비에 10℃'],['常温','상온 20℃'],
           ['ぬる燗','누루칸 40℃'],['熱燗','아츠칸 50℃']];
var PREM=['十四代','而今','飛露喜','新政','黒龍','磯自慢','勝駒','花陽浴','射美'];
var CAT=[], MINE={}, NOTE={}, dexN=60, curId=null;

function load(k,d){try{return JSON.parse(localStorage.getItem(k))||d}catch(e){return d}}
/* 노트는 [{at,mine,tags,temp,memo,again}, ...] 로 쌓인다. 같은 술을 다시 마시면
   덮어쓰지 않고 붙는다 — 사케는 온도·상태로 인상이 달라져서 이전 기록이 정보다.
   초기 버전은 객체 하나였으므로 읽을 때 배열로 올린다. */
function logsOf(id){
  var n=NOTE[id]; if(!n)return [];
  if(Array.isArray(n))return n;
  return [n];
}
function lastLog(id){var l=logsOf(id);return l.length?l[l.length-1]:null}
/* 카드 한 장은 **제품 한 병**이다. 도감(catalog.json)은 브랜드 단위라
   한 브랜드에 여러 제품이 걸린다 — 브랜드로 키를 잡으면 칸키쿠 14병이 한 장으로
   뭉쳐 컬렉션이 무너진다(2026-09-16 실측: 135병을 담았는데 카드 71장).
   그래서 카드 키는 `<도감id>#<제품명>` 이고, 제품명이 없으면 도감 id 그대로다. */
function baseOf(id){var i=String(id).indexOf('#');return i<0?String(id):String(id).slice(0,i)}
function prodOf(id){var i=String(id).indexOf('#');return i<0?'':String(id).slice(i+1)}
function catOf(id){var b=baseOf(id);for(var i=0;i<CAT.length;i++)if(CAT[i].id===b)return CAT[i];return null}
/* 도감 카드(브랜드)에 「所持」를 붙일지 — 그 브랜드로 담은 병이 하나라도 있으면 붙인다 */
function ownedBrand(bid){for(var k in MINE)if(baseOf(k)===bid)return true;return false}
function notedBrand(bid){for(var k in NOTE)if(baseOf(k)===bid)return true;return false}
function variantsOf(bid){var o=[];for(var k in MINE)if(baseOf(k)===bid)o.push(k);return o}
/* 카드 한 장 = 도감 정보 + 내가 담은 병의 제품명 */
function cardOf(id){
  var c=catOf(id), m=MINE[id]||{}, pr=prodOf(id), o={};
  if(c)for(var k in c)o[k]=c[k];
  o.id=id;
  o.jp=c?c.jp:(m.jp||'?');
  /* 제품명을 모르는 병은 브랜드명이 제품명 자리에 들어와 있다(사진으로만 찾은 술).
     그대로 두면 같은 이름이 두 줄로 겹치므로 한국어 독음으로 바꾼다. */
  o.ko=pr||m.name||'';
  if(c&&o.ko===c.jp)o.ko='';
  if(!o.ko&&c)o.ko=c.ko||'';
  o.area=o.area||''; o.brewery=o.brewery||'';
  if(!('f' in o))o.f=null;
  o.at=m.at||'';
  return o;
}
function save(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch(e){toast('저장 공간이 부족합니다')}}
function $(s){return document.querySelector(s)}
function $$(s){return [].slice.call(document.querySelectorAll(s))}
function esc(s){return String(s==null?'':s).replace(/[&<>"]/g,function(c){
  return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
/* 조사 — 받침 유무로 고른다. 한글이 아니면(일본어·영문 검색어) 받침 없는 쪽을 쓴다. */
function josa(w,withBat,noBat){
  var c=String(w||'').trim().slice(-1);
  if(!c)return noBat;
  var code=c.charCodeAt(0);
  if(code>=0xac00&&code<=0xd7a3)return (code-0xac00)%28?withBat:noBat;
  return noBat;
}
function toast(m){var t=$('#toast');t.textContent=m;t.classList.add('on');
  clearTimeout(toast._t);toast._t=setTimeout(function(){t.classList.remove('on')},1800)}

/* ── 카드 ── */
function isPrem(s){for(var i=0;i<PREM.length;i++)if(s.jp.indexOf(PREM[i])>=0)return true;return false}
function hue(f){ /* 가벼움↔묵직함으로 밴드 색을 잡는다 */
  var light=f[5], rich=f[1];
  var t=Math.max(0,Math.min(1,(rich-light+1)/2));
  return Math.round(90 - t*70);
}
/* 카드 얼굴 — 맛 6축을 작게 그린다. 이게 없으면 카드 위쪽이 통째로 빈 공간이라
   카드를 모으는 앱인데 모을 맛이 안 난다(2026-09-16 지적).
   내가 그린 값이 있으면 그걸, 없으면 도감 평균을 흐리게 얹는다. */
function miniRadar(f,mine,dark){
  var C=50,R=34,s=[];
  function pt(i,v){var a=-Math.PI/2+i*Math.PI/3;return [C+Math.cos(a)*R*v,C+Math.sin(a)*R*v]}
  function poly(v){return v.map(function(x,i){return pt(i,Math.max(.06,x)).join(',')}).join(' ')}
  var web=dark?'rgba(201,168,106,.22)':'rgba(33,29,24,.13)';
  s.push('<polygon points="'+poly([1,1,1,1,1,1])+'" fill="none" stroke="'+web+'"/>');
  s.push('<polygon points="'+poly([.5,.5,.5,.5,.5,.5])+'" fill="none" stroke="'+web+'"/>');
  for(var i=0;i<6;i++){var p=pt(i,1);
    s.push('<line x1="'+C+'" y1="'+C+'" x2="'+p[0]+'" y2="'+p[1]+'" stroke="'+web+'"/>')}
  var col=dark?'#c9a86a':'var(--me)';
  if(mine){
    if(f)s.push('<polygon points="'+poly(f)+'" fill="none" stroke="'+web+'" stroke-dasharray="2 2"/>');
    s.push('<polygon points="'+poly(mine)+'" fill="'+col+'" fill-opacity="'+(dark?'.26':'.2')
      +'" stroke="'+col+'" stroke-width="1.6"/>');
  }else if(f){
    s.push('<polygon points="'+poly(f)+'" fill="'+col+'" fill-opacity="'+(dark?'.14':'.1')
      +'" stroke="'+col+'" stroke-opacity=".55" stroke-width="1.2"/>');
  }
  return '<svg class="mini" viewBox="0 0 100 100" aria-hidden="true">'+s.join('')+'</svg>';
}
function cardHTML(s,opts){
  opts=opts||{};
  var prem=isPrem(s), mine=!!MINE[s.id]||ownedBrand(s.id), noted=!!NOTE[s.id]||notedBrand(s.id);
  var f=s.f||[.5,.5,.5,.5,.5,.5];
  var log=lastLog(s.id);
  return '<div class="c'+(prem?' prem':'')+(opts.locked&&!mine?' locked':'')+'" data-id="'+esc(s.id)+'">'
    +'<div class="band" style="background:hsl('+hue(f)+',42%,56%)"></div>'
    +miniRadar(s.f,log&&log.mine,prem)
    +'<div class="glyph">酒</div>'
    +(noted?'<div class="noted">筆</div>':'')
    +'<div class="jp">'+esc(s.jp)+'</div>'
    +'<div class="ko">'+esc(s.ko||s.brewery||'')+'</div>'
    +'<div class="foot"><span>'+esc(s.area||'')+'</span><span>'+(mine?'所持':'')+'</span></div>'
    +'</div>';
}

/* ── 도감 ── */
var dexFilter='all';
function dexList(){
  var q=($('#q').value||'').trim().toLowerCase();
  var out=CAT.filter(function(s){
    if(dexFilter==='mine'&&!ownedBrand(s.id))return false;
    if(dexFilter==='new'&&ownedBrand(s.id))return false;
    if(!q)return true;
    return (s.jp+' '+(s.ko||'')+' '+(s.area||'')+' '+(s.brewery||'')).toLowerCase().indexOf(q)>=0;
  });
  if($('#sort').value==='jp')out.sort(function(a,b){return a.jp.localeCompare(b.jp,'ja')});
  return out;
}
function renderDex(){
  var list=dexList(), shown=list.slice(0,dexN);
  $('#dex-grid').innerHTML=shown.map(function(s){return cardHTML(s,{locked:true})}).join('');
  $('#dex-count').textContent=list.length+'종'+(list.length>shown.length?' 중 '+shown.length+'종 표시':'');
  $('#dex-more').hidden=list.length<=shown.length;
  var none=$('#dex-none'); if(none){
    var q=($('#q').value||'').trim();
    none.querySelector('h3').textContent = list.length===0 && q
      ? '\u300c'+q+'\u300d'+josa(q,'\uc744','\ub97c')+' \ucc3e\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4'
      : '\ucc3e\ub294 \uc220\uc774 \uc5c6\ub098\uc694?';
  }
}
/* ── 내 카드 ── */
var mineFilter='all';
function mineList(){
  var q=($('#mq').value||'').trim().toLowerCase();
  var out=Object.keys(MINE).map(cardOf);
  if(mineFilter==='noted')out=out.filter(function(s){return NOTE[s.id]});
  if(mineFilter==='blank')out=out.filter(function(s){return !NOTE[s.id]});
  if(q)out=out.filter(function(s){return (s.jp+' '+(s.ko||'')+' '+(s.area||'')+' '+(s.brewery||'')).toLowerCase().indexOf(q)>=0});
  if($('#msort').value==='jp')out.sort(function(a,b){return a.jp.localeCompare(b.jp,'ja')});
  else out.sort(function(a,b){return (b.at||'').localeCompare(a.at||'')});
  return out;
}
function renderMine(){
  var list=mineList(), has=Object.keys(MINE).length>0;
  var q=($('#mq').value||'').trim();
  /* 담은 카드는 있는데 검색·필터로 0건이면 빈 화면만 남아 고장처럼 보인다 */
  $('#mine-grid').innerHTML = list.length
    ? list.map(function(s){return cardHTML(s)}).join('')
    : (has ? '<p class="diff" style="grid-column:1/-1;text-align:center;padding:24px 8px">'
        +(q?'담은 카드 중에 <b>「'+esc(q)+'」</b>'+josa(q,'을','를')+' 찾지 못했습니다.'
           :'이 조건에 맞는 카드가 없습니다.')+'</p>' : '');
  $('#mine-count').textContent=list.length+'종';
  $('#mine-empty').hidden=has;
}
/* ── 홈 ── */
function renderHome(){
  var ids=Object.keys(MINE);
  $('#s-mine').textContent=ids.length;
  $('#s-note').textContent=Object.keys(NOTE).reduce(function(a,k){return a+logsOf(k).length},0);
  var brews={};ids.forEach(function(id){var s=catOf(id);
    if(s&&s.brewery)brews[s.brewery]=1});
  $('#s-brew').textContent=Object.keys(brews).length;
  var bset={};ids.forEach(function(id){bset[baseOf(id)]=1});
  $('#s-brand').textContent=Object.keys(bset).length;
  $('#home-empty').hidden=ids.length>0;
  var gauge=$('#home-gauge');
  if(gauge){
    var brands={};ids.forEach(function(id){if(catOf(id))brands[baseOf(id)]=1});
    var nb=Object.keys(brands).length, na=Object.keys(areaCount()).length;
    gauge.hidden=!ids.length;
    if(ids.length)gauge.innerHTML=
       bar('도감', nb, CAT.length, nb+' / '+CAT.length+'종')
      +bar('지역', na, 47, na+' / 47곳');
  }
  /* 담기만 하고 노트를 안 쓴 카드가 쌓이면 어디서부터 손댈지가 막막하다.
     첫 장을 바로 열어 준다 — 저장하면 다음 장이 이어서 열린다. */
  var blank=$('#home-todo');
  if(blank){
    var left=blankIds(null).length;
    blank.hidden=!left;
    if(left)blank.innerHTML='<div style="display:flex;align-items:center;gap:12px">'
      +'<span style="flex:1;font-size:13.5px;word-break:keep-all">'
      +'맛을 안 그린 카드가 <b>'+left+'장</b> 남았습니다</span>'
      +'<button class="pri" id="go-blank" style="flex:0 0 auto;padding:9px 16px">채우기</button></div>';
  }
  var recent=mineList().slice(0,6);
  $('#home-recent').innerHTML = recent.length
    ? '<p class="count" style="margin-top:18px">최근 담은 카드</p><div class="grid">'
      +recent.map(function(s){return cardHTML(s)}).join('')+'</div>' : '';
}
/* 담아만 두고 노트를 안 쓴 카드. 세정님처럼 135장을 먼저 담아 둔 경우
   한 장씩 찾아 여는 게 일이라, 저장하고 바로 다음 장으로 넘어갈 수 있게 한다. */
function blankIds(exceptId){
  return mineList().filter(function(s){
    return s.id!==exceptId && !logsOf(s.id).length;
  }).map(function(s){return s.id});
}
function blankLeft(id){return blankIds(id).length}
function nextBlank(id){var b=blankIds(id);return b.length?b[0]:null}
/* 마신 술의 지역 분포. 사케는 지역색이 뚜렷해서 「어디를 마셨나」가 곧 취향의 지도다.
   도감에 없는 술(own:)은 지역을 모르므로 세지 않는다 — 없는 값을 채우지 않는다. */
function areaCount(){
  var o={};
  Object.keys(MINE).forEach(function(id){
    var s=catOf(id); if(!s||!s.area)return;
    o[s.area]=(o[s.area]||0)+1;
  });
  return o;
}
/* 얼마나 모았나 — 한 줄짜리 막대 */
function bar(label,v,max,right){
  var pct=max?Math.min(100,v/max*100):0;
  return '<div style="display:flex;align-items:center;gap:9px;margin:7px 0">'
    +'<span style="flex:0 0 32px;font-size:11.5px;color:var(--ink3)">'+label+'</span>'
    +'<span style="flex:1;height:8px;background:var(--hair);border-radius:4px;overflow:hidden">'
    +'<span style="display:block;height:100%;width:'+(pct<1.2?1.2:pct)+'%;background:var(--me)"></span></span>'
    +'<span style="flex:0 0 76px;text-align:right;font-size:11px;color:var(--ink3)">'+esc(right)+'</span>'
    +'</div>';
}
/* ── 분석 ── */
function renderStats(){
  var body=$('#stat-body'); if(!body)return;
  var has=Object.keys(MINE).length>0;
  var el=$('#stat-empty'); if(el)el.hidden=has;
  if(!has){body.innerHTML='';return}
  var notes=Object.keys(NOTE).reduce(function(a,k){return a+logsOf(k).length},0);
  body.innerHTML=
     '<div class="empty" style="text-align:left" id="st-sum"></div>'
    +'<div class="empty" style="text-align:left;margin-top:12px" id="st-brand"></div>'
    +'<div class="empty" style="text-align:left;margin-top:12px" id="me-area"></div>'
    +'<div class="empty" style="text-align:left;margin-top:12px" id="st-todo"></div>'
    +'<div class="empty" style="text-align:left;margin-top:12px" id="me-taste"></div>'
    +'<div class="empty" style="text-align:left;margin-top:12px" id="st-like"></div>';
  renderSum(notes); renderBrandTop(); renderArea(); renderUnvisited();
  renderTaste(notes); renderLike();
}
/* 한눈 요약 — 몇 병을 어디까지 모았나 */
function renderSum(notes){
  var box=$('#st-sum'); if(!box)return;
  var ids=Object.keys(MINE), brews={}, brands={};
  ids.forEach(function(id){var c=catOf(id);
    if(c&&c.brewery)brews[c.brewery]=1;
    brands[baseOf(id)]=1});
  box.innerHTML='<h3>모은 것</h3>'
    +'<p class="diff" style="margin-top:8px;font-size:14px;line-height:2">'
    +'병 <b>'+ids.length+'</b> · 브랜드 <b>'+Object.keys(brands).length+'</b>'
    +' · 양조장 <b>'+Object.keys(brews).length+'</b><br>'
    +'지역 <b>'+Object.keys(areaCount()).length+'</b>곳 · 테이스팅 노트 <b>'+notes+'</b>건</p>'
    + (notes? '' : '<p class="diff" style="color:var(--ink3)">노트를 쓰면 아래에 취향이 그려집니다.</p>');
}
/* 많이 마신 브랜드 — 같은 이름이라도 병은 다르니 병 수로 센다 */
function renderBrandTop(){
  var box=$('#st-brand'); if(!box)return;
  var cnt={};
  Object.keys(MINE).forEach(function(id){var b=baseOf(id);cnt[b]=(cnt[b]||0)+1});
  var ks=Object.keys(cnt).sort(function(a,b){return cnt[b]-cnt[a]});
  if(cnt[ks[0]]<2){box.hidden=true;return}
  box.hidden=false;
  var top=ks.slice(0,6), mx=cnt[top[0]];
  box.innerHTML='<h3>많이 마신 브랜드</h3><div style="margin-top:10px">'
    + top.map(function(k){
        var c=catOf(k), nm=c?c.jp:(MINE[k]||{}).jp||'?', ko=(c&&c.ko)||'';
        return '<div style="display:flex;align-items:center;gap:8px;margin:7px 0">'
          +'<span style="flex:0 0 96px;word-break:keep-all">'
          +'<b style="font-family:var(--disp);font-size:15px">'+esc(nm)+'</b>'
          +(ko?'<br><span style="font-size:10.5px;color:var(--ink3)">'+esc(ko)+'</span>':'')+'</span>'
          +'<span style="flex:1;height:9px;background:var(--hair);border-radius:5px;overflow:hidden">'
          +'<span style="display:block;height:100%;width:'+Math.round(cnt[k]/mx*100)+'%;background:var(--me)"></span></span>'
          +'<span style="flex:0 0 30px;text-align:right;font-size:11.5px;color:var(--ink3)">'+cnt[k]+'병</span>'
          +'</div>'}).join('')
    +'</div>';
}
/* 아직 안 마신 지역 — 모으는 재미 */
function renderUnvisited(){
  var box=$('#st-todo'); if(!box)return;
  var mine=areaCount(), all={};
  CAT.forEach(function(c){if(c.area)all[c.area]=(all[c.area]||0)+1});
  var left=Object.keys(all).filter(function(a){return !mine[a]});
  if(!left.length){box.hidden=true;return}
  box.hidden=false;
  left.sort(function(a,b){return all[b]-all[a]});
  box.innerHTML='<h3>아직 안 마신 지역 '+left.length+'곳</h3>'
    +'<p class="diff">도감에 술이 많은 순입니다. 눌러서 찾아보세요.</p>'
    +'<div class="chips" style="margin-top:10px">'
    + left.slice(0,10).map(function(a){
        return '<div class="chip" data-area="'+esc(a)+'">'+esc(a)
          +' <span style="opacity:.6;font-size:10px">'+all[a]+'</span></div>'}).join('')
    +'</div>';
}
/* 취향에 가까운 술 — 내가 그린 6축 평균과 거리가 가까운 것 중 아직 안 담은 것.
   도감 맛 데이터와 내 기록만으로 고른다(추천 점수를 지어내지 않는다). */
function renderLike(){
  var box=$('#st-like'); if(!box)return;
  var sum=[0,0,0,0,0,0], n=0;
  Object.keys(NOTE).forEach(function(id){
    logsOf(id).forEach(function(l){
      if(!l.mine)return; l.mine.forEach(function(v,i){sum[i]+=v}); n++});
  });
  if(n<3){
    box.innerHTML='<h3>취향에 가까운 술</h3>'
      +'<p>노트가 <b>'+n+'건</b>입니다. 3건부터 도감에서 비슷한 맛을 찾아 줍니다.</p>';
    return;
  }
  var avg=sum.map(function(v){return v/n});
  var out=CAT.filter(function(c){return c.f&&!ownedBrand(c.id)})
    .map(function(c){
      var d=0; c.f.forEach(function(v,i){d+=(v-avg[i])*(v-avg[i])});
      return {c:c,d:Math.sqrt(d)}})
    .sort(function(a,b){return a.d-b.d}).slice(0,6);
  box.innerHTML='<h3>취향에 가까운 술 <span style="font-weight:400;color:var(--ink3)">노트 '+n+'건 기준</span></h3>'
    +'<p class="diff">내가 그린 맛 평균과 가까운, 아직 안 담은 술입니다.</p>'
    +'<div class="grid" style="margin-top:12px">'
    + out.map(function(o){return cardHTML(o.c,{locked:true})}).join('')
    +'</div>';
}
function renderArea(){
  var box=$('#me-area'); if(!box)return;
  var cnt=areaCount(), names=Object.keys(cnt);
  if(!names.length){
    box.innerHTML='<h3>지역 지도</h3><p>카드를 담으면 <b>어느 지역 술을 마셨는지</b>가 여기에 쌓입니다.'
      +'<br>일본 47개 도도부현 중 몇 곳을 마셨는지 셉니다.</p>';
    return;
  }
  names.sort(function(a,b){return cnt[b]-cnt[a]||a.localeCompare(b,'ko')});
  var max=cnt[names[0]], shown=names.slice(0,10), rest=names.length-shown.length;
  var unknown=Object.keys(MINE).length-names.reduce(function(a,k){return a+cnt[k]},0);
  box.innerHTML='<h3>지역 지도 <span style="font-weight:400;color:var(--ink3)">'
      +names.length+' / 47곳</span></h3>'
    +'<div style="margin-top:10px">'
    + shown.map(function(n){
        return '<div style="display:flex;align-items:center;gap:8px;margin:5px 0">'
          +'<span style="flex:0 0 64px;font-size:11.5px;color:var(--ink2);word-break:keep-all">'+esc(n)+'</span>'
          +'<span style="flex:1;height:9px;background:var(--hair);border-radius:5px;overflow:hidden">'
          +'<span style="display:block;height:100%;width:'+Math.round(cnt[n]/max*100)+'%;background:var(--me)"></span></span>'
          +'<span style="flex:0 0 26px;text-align:right;font-size:11.5px;color:var(--ink3)">'+cnt[n]+'</span>'
          +'</div>'}).join('')
    +'</div>'
    +(rest>0?'<p class="diff" style="margin-top:8px">그 밖에 '+rest+'곳을 더 마셨습니다.</p>':'')
    +(unknown>0?'<p class="diff" style="font-size:11.5px;color:var(--ink3)">도감에 없는 '+unknown
      +'장은 지역을 몰라 세지 않았습니다.</p>':'');
}
/* ── 상세 시트 ── */
function radarSVG(mine,ref,id){
  var CX=150,CY=140,R=96,s=[];
  function pt(i,v){var a=-Math.PI/2+i*Math.PI/3;return [CX+Math.cos(a)*R*v,CY+Math.sin(a)*R*v]}
  function poly(v){return v.map(function(x,i){return pt(i,Math.max(.04,x)).join(',')}).join(' ')}
  s.push('<g stroke="var(--hair)" fill="none">');
  [.25,.5,.75,1].forEach(function(r){s.push('<polygon points="'+poly([r,r,r,r,r,r])+'" opacity=".5"/>')});
  for(var i=0;i<6;i++){var p=pt(i,1);s.push('<line x1="'+CX+'" y1="'+CY+'" x2="'+p[0]+'" y2="'+p[1]+'" opacity=".4"/>')}
  s.push('</g>');
  if(ref)s.push('<polygon points="'+poly(ref)+'" fill="var(--ink3)" fill-opacity=".13" stroke="var(--ink3)" stroke-width="1.3" stroke-dasharray="3 3"/>');
  s.push('<polygon points="'+poly(mine)+'" fill="var(--me)" fill-opacity=".2" stroke="var(--me)" stroke-width="2.2"/>');
  AX.forEach(function(a,i){var p=pt(i,1.26);
    s.push('<text x="'+p[0]+'" y="'+p[1]+'" text-anchor="middle" font-size="12" fill="var(--ink2)" font-family="Yu Mincho,serif">'+a[0]+'</text>');
    s.push('<text x="'+p[0]+'" y="'+(p[1]+11)+'" text-anchor="middle" font-size="9" fill="var(--ink3)">'+a[1]+'</text>');
    var q=pt(i,mine[i]);
    s.push('<circle cx="'+q[0]+'" cy="'+q[1]+'" r="9" fill="var(--me)" data-ax="'+i+'" style="cursor:grab"/>')});
  return '<svg class="radar"'+(id?' id="'+id+'"':'')+' viewBox="0 0 300 290" style="touch-action:none">'
    +s.join('')+'</svg>';
}
function openSheet(id){
  curId=id;
  if(!catOf(id)&&!MINE[id])return;
  var s=cardOf(id);
  var has=!!MINE[id], logs=logsOf(id), n=lastLog(id);
  /* 도감에서 브랜드를 열었는데 그 브랜드로 담은 병이 있으면 먼저 보여준다 —
     같은 브랜드의 다른 병을 또 담아 중복이 생기는 걸 막는다. */
  var vars_= has?[]:variantsOf(id);
  var _c=catOf(id), c_ko=(_c&&_c.ko)||'';
  if(c_ko&&(s.ko||'').indexOf(c_ko)===0)c_ko='';   /* 제품명이 이미 독음으로 시작하면 중복 */
  var mine=n?n.mine.slice():(s.f?s.f.slice():[.5,.5,.5,.5,.5,.5]);
  var st={tags:n?n.tags.slice():[],temp:n?n.temp:null,memo:n?n.memo:'',again:n?n.again:null,
          at:(n&&n.at?n.at.slice(0,10):((MINE[id]||{}).at||new Date().toISOString().slice(0,10)))};
  function chips(){return TAGS.map(function(t){
    return '<div class="chip'+(st.tags.indexOf(t[0])>=0?' on':'')+'" data-tag="'+t[0]+'">'
      +'<b style="font-family:var(--disp)">'+t[0]+'</b> <span style="opacity:.7;font-size:10px">'+t[1]+'</span></div>'}).join('')}
  function temps(){return TEMPS.map(function(t,i){
    return '<div class="temp'+(st.temp===i?' on':'')+'" data-temp="'+i+'"><b>'+t[0]+'</b><span>'+t[1]+'</span></div>'}).join('')}
  function agains(){return ['또 마신다','글쎄','한 번이면 족해'].map(function(t,i){
    return '<div class="ag'+(st.again===i?' on':'')+'" data-ag="'+i+'">'+t+'</div>'}).join('')}
  $('#sheetbox').innerHTML='<div class="bar"></div>'
    +'<h2>'+esc(s.jp)+(c_ko?' <span style="font-size:14px;color:var(--ink3);font-family:var(--body);letter-spacing:0">'+esc(c_ko)+'</span>':'')+'</h2><p class="meta">'
    +esc([s.ko,s.brewery,s.area&&s.areaJp&&s.area!==s.areaJp?s.area+' '+s.areaJp:(s.area||s.areaJp||'')]
          .filter(Boolean).join(' · '))+'</p>'
    +'<div class="acts">'
    + (has ? '<button class="pri" id="a-note">테이스팅 노트 저장</button>'
           + '<button id="a-img">이미지로 저장</button>'
           + (catOf(id)?'<button id="a-more">같은 술 다른 병 담기</button>':'')
           : '<button class="pri" id="a-add">마셨어요 — 카드로 담기</button>')
    +'<button class="ghost" id="a-close">닫기</button></div>'
    + (has ? '<div id="noteui">'
        +radarSVG(mine,s.f,'rad')
        +'<p class="legend">'+(s.f?'<span style="color:var(--ink3)">— — 데이터 평균</span> &nbsp; ':'')
        +'<span style="color:var(--me)">—— 내가 느낀 값</span></p>'
        +'<p class="diff" id="diff"></p>'
        +'<div class="sec"><h3>맛 · 향</h3><div class="chips" id="c-tags">'+chips()+'</div></div>'
        +'<div class="sec"><h3>마신 온도</h3><div class="temps" id="c-temps">'+temps()+'</div></div>'
        +'<div class="sec"><h3>마신 날</h3><input type="date" id="c-at" value="'+esc(st.at)+'"'
        +' max="'+new Date().toISOString().slice(0,10)+'"></div>'
        +'<div class="sec"><h3>한 줄</h3><textarea id="c-memo" placeholder="그날의 기분, 안주, 자리">'+esc(st.memo)+'</textarea></div>'
        +'<div class="sec"><h3>또 마실까</h3><div class="again" id="c-again">'+agains()+'</div></div>'
        + (logs.length ? '<div class="sec"><h3>지난 기록 '+logs.length+'회</h3><div class="hist">'
            + logs.slice().reverse().map(function(l,i){
                var idx=logs.length-1-i;
                return '<div class="hrow" data-log="'+idx+'"><b>'+esc((l.at||'').slice(0,10))+'</b>'
                  +'<span>'+esc(l.memo||(l.tags||[]).join(' · ')||'기록')+'</span></div>'}).join('')
            + '</div><p class="diff" style="margin-top:8px;font-size:11.5px">'
            + '탭하면 그때 그린 값을 불러옵니다. 저장하면 <b>새 기록으로 쌓입니다</b>.</p></div>' : '')
        + (blankLeft(id)
            ? '<div class="acts" style="margin-top:18px">'
              +'<button class="pri" id="a-next">저장하고 다음 카드 ('+blankLeft(id)+'장 남음)</button></div>'
            : '')
        +'<div class="acts" style="margin-top:18px"><button class="del" id="a-del">컬렉션에서 빼기</button></div>'
        +'</div>'
      : (vars_.length
          ? '<div class="sec"><h3>이 술로 담은 병 '+vars_.length+'개</h3><div class="hist">'
            + vars_.map(function(k){var c=cardOf(k);
                return '<div class="hrow" data-open="'+esc(k)+'"><b>'+esc((c.at||'').slice(0,10))+'</b>'
                  +'<span>'+esc(c.ko||c.jp)+'</span></div>'}).join('')
            + '</div><p class="diff" style="margin-top:8px;font-size:11.5px">탭하면 그 병의 카드를 엽니다.</p></div>'
          : '')
        + '<p class="diff" style="margin-top:14px">'
        + (vars_.length?'다른 병을 마셨다면 위 버튼으로 담으세요.':'아직 담지 않은 술입니다. 담으면 테이스팅 노트를 쓸 수 있습니다.')
        + '</p>');
  $('#sheet').classList.add('on');

  function diff(){
    var el=$('#diff'); if(!el)return;
    if(!s.f){el.innerHTML='<b>도감에 맛 데이터가 없는 술</b>입니다 — 지금 그린 값이 첫 기록이 됩니다.';return}
    var d=[];mine.forEach(function(v,i){var g=v-s.f[i];
      if(Math.abs(g)>.18)d.push(AX[i][1]+(g>0?' 더 강하게':' 더 약하게'))});
    el.innerHTML=d.length?'데이터보다 <b>'+d.join('</b>, <b>')+'</b> 느꼈습니다.':'데이터 평균과 비슷하게 느꼈습니다.';
  }
  function redrawRadar(){
    var wrap=$('#noteui'); if(!wrap)return;
    var old=wrap.querySelector('#rad'); if(old)old.outerHTML=radarSVG(mine,s.f,'rad');
    bindRadar(); diff();
  }
  function bindRadar(){
    var rad=$('#noteui #rad'); if(!rad)return; var drag=null;
    function xy(e){var r=rad.getBoundingClientRect(),t=e.touches?e.touches[0]:e;
      return [(t.clientX-r.left)*300/r.width,(t.clientY-r.top)*290/r.height]}
    rad.addEventListener('pointerdown',function(e){
      if(e.target.tagName!=='circle')return; drag=+e.target.dataset.ax;
      rad.setPointerCapture(e.pointerId); e.preventDefault()});
    rad.addEventListener('pointermove',function(e){
      if(drag===null)return; var p=xy(e),a=-Math.PI/2+drag*Math.PI/3;
      var v=((p[0]-150)*Math.cos(a)+(p[1]-140)*Math.sin(a))/96;
      mine[drag]=Math.max(0,Math.min(1,v)); redrawRadar(); e.preventDefault()});
    rad.addEventListener('pointerup',function(){drag=null});
    rad.addEventListener('pointercancel',function(){drag=null});
  }
  bindRadar(); diff();

  /* 같은 브랜드라도 병마다 다른 술이다(칸키쿠만 14병). 담을 때 한 번 물어
     카드가 병 단위로 남게 한다 — 비우면 브랜드 카드 한 장으로 담긴다. */
  function askProd(){
    var old=$('#prodask'); if(old){old.scrollIntoView({block:'center'});$('#p-name').focus();return}
    var el=document.createElement('div');
    el.id='prodask'; el.className='sec';
    el.innerHTML='<h3>어떤 병이었나요 <span style="color:var(--ink3);font-weight:400">(선택)</span></h3>'
      +'<textarea id="p-name" style="min-height:42px" placeholder="예: 준마이다이긴죠 나마 720ml"></textarea>'
      +'<div class="acts" style="margin-top:10px">'
      +'<button class="pri" id="p-ok">이 이름으로 담기</button>'
      +'<button class="ghost" id="p-skip">이름 없이 담기</button></div>';
    $('#sheetbox').appendChild(el);
    el.scrollIntoView({block:'center'}); $('#p-name').focus();
  }

  var box=$('#sheetbox');
  box.onclick=function(e){
    var t=e.target.closest('[data-tag],[data-temp],[data-ag],[data-log],[data-open],'
      +'#a-add,#a-more,#a-del,#a-note,#a-next,#a-img,#a-close,#p-ok,#p-skip');
    if(!t)return;
    if(t.dataset.open!==undefined){openSheet(t.dataset.open);return}
    if(t.dataset.tag!==undefined){var i=st.tags.indexOf(t.dataset.tag);
      i<0?st.tags.push(t.dataset.tag):st.tags.splice(i,1);$('#c-tags').innerHTML=chips();return}
    if(t.dataset.temp!==undefined){st.temp=+t.dataset.temp;$('#c-temps').innerHTML=temps();return}
    if(t.dataset.ag!==undefined){st.again=+t.dataset.ag;$('#c-again').innerHTML=agains();return}
    if(t.dataset.log!==undefined){
      var l=logsOf(id)[+t.dataset.log]; if(!l)return;
      mine=l.mine.slice(); st={tags:(l.tags||[]).slice(),temp:l.temp,memo:l.memo||'',again:l.again,
                               at:(l.at||'').slice(0,10)||st.at};
      var ta=$('#c-memo'); if(ta)ta.value=st.memo;
      var da=$('#c-at'); if(da)da.value=st.at;
      $('#c-tags').innerHTML=chips(); $('#c-temps').innerHTML=temps(); $('#c-again').innerHTML=agains();
      redrawRadar(); toast((l.at||'').slice(0,10)+' 기록을 불러왔습니다'); return}
    if(t.id==='a-img'){exportCard(id);return}
    if(t.id==='a-close'){closeSheet();return}
    if(t.id==='a-add'||t.id==='a-more'){askProd();return}
    if(t.id==='p-ok'||t.id==='p-skip'){
      var pn=t.id==='p-ok'?(($('#p-name')||{}).value||'').trim():'';
      var key=pn?baseOf(id)+'#'+pn:baseOf(id);
      if(MINE[key]){toast('이미 담은 병입니다');openSheet(key);return}
      MINE[key]={at:new Date().toISOString().slice(0,10),jp:s.jp,name:pn};
      save(K_MINE,MINE); toast('카드에 담았습니다'); refresh(); openSheet(key); return}
    if(t.id==='a-del'){
      if(!confirm('이 카드를 컬렉션에서 뺍니다. 노트도 함께 지워집니다.'))return;
      delete MINE[id]; delete NOTE[id]; save(K_MINE,MINE); save(K_NOTE,NOTE);
      toast('뺐습니다'); closeSheet(); refresh(); return}
    if(t.id==='a-note'||t.id==='a-next'){
      st.memo=($('#c-memo')||{}).value||'';
      var day=($('#c-at')||{}).value||'';
      var arr=logsOf(id).slice();
      arr.push({at:day?day+'T00:00:00.000Z':new Date().toISOString(),
                mine:mine,tags:st.tags,temp:st.temp,memo:st.memo,again:st.again});
      NOTE[id]=arr; save(K_NOTE,NOTE);
      refresh();
      if(t.id==='a-next'){
        var nx=nextBlank(id);
        if(nx){toast('저장했습니다 — 다음 카드');openSheet(nx);return}
        toast('저장했습니다 — 안 쓴 카드가 없습니다');closeSheet();return}
      toast(arr.length>1?'새 기록으로 쌓았습니다 ('+arr.length+'회)':'노트를 저장했습니다');
      closeSheet(); return}
  };
}
function openManual(){
  $('#sheetbox').innerHTML='<div class="bar"></div>'
    +'<h2>직접 추가</h2><p class="meta">도감에 없는 술을 카드로 만듭니다.</p>'
    +'<div class="sec"><h3>사케명 <span style="color:#a8534a">*</span></h3>'
    +'<textarea id="m-jp" style="min-height:42px" placeholder="예: 埋火 · 우즈미비"></textarea></div>'
    +'<div class="sec"><h3>양조장 · 지역 (선택)</h3>'
    +'<textarea id="m-ko" style="min-height:42px" placeholder="예: 山口県"></textarea></div>'
    +'<div class="acts"><button class="pri" id="m-save">카드로 담기</button>'
    +'<button class="ghost" id="m-cancel">취소</button></div>';
  $('#sheet').classList.add('on');
  $('#sheetbox').onclick=function(e){
    var t=e.target.closest('#m-save,#m-cancel'); if(!t)return;
    if(t.id==='m-cancel'){closeSheet();return}
    var jp=($('#m-jp').value||'').trim();
    if(!jp){toast('사케명을 입력해 주세요');return}
    var id='own:'+Date.now().toString(36);
    MINE[id]={at:new Date().toISOString().slice(0,10),jp:jp,name:($('#m-ko').value||'').trim()};
    save(K_MINE,MINE); toast('담았습니다'); closeSheet(); refresh(); go('mine');
  };
}
function tagKo(jp){for(var i=0;i<TAGS.length;i++)if(TAGS[i][0]===jp)return TAGS[i][1];return jp}
/* 캔버스 줄바꿈 — 폭을 넘으면 접고, 최대 줄 수를 넘으면 말줄임 */
function wrapText(x,text,cx,y,maxW,lh,maxLines){
  var words=String(text||'').split(/\s+/).filter(Boolean), lines=[], cur='';
  words.forEach(function(w){
    var t=cur?cur+' '+w:w;
    if(x.measureText(t).width<=maxW){cur=t;return}
    if(cur)lines.push(cur);
    cur=w;
  });
  if(cur)lines.push(cur);
  if(lines.length>maxLines){lines=lines.slice(0,maxLines);
    lines[maxLines-1]=lines[maxLines-1].replace(/.$/,'')+'…'}
  lines.forEach(function(l,i){x.fillText(l,cx,y+i*lh)});
  return lines.length;
}
/* 카드를 이미지로 — 인스타 피드 비율(4:5). 화면 카드는 CSS 로 그려서 캡처가 안 되므로
   Canvas 에 다시 그린다. 외부 라이브러리 없이 끝난다. */
function exportCard(id){
  if(!catOf(id)&&!MINE[id])return;
  var s=cardOf(id);
  var log=lastLog(id), prem=isPrem(s);
  var W=1080,H=1350,c=document.createElement('canvas');c.width=W;c.height=H;
  var x=c.getContext('2d');
  var dark=prem, bg=dark?'#1c1a16':'#f4f1e9', ink=dark?'#efe6d4':'#211d18',
      ink2=dark?'#b7ac97':'#6b655b', hair=dark?'rgba(201,168,106,.28)':'#cfc7b6';
  x.fillStyle=bg;x.fillRect(0,0,W,H);
  /* 상단 맛색 밴드 */
  x.fillStyle='hsl('+hue(s.f||[.5,.5,.5,.5,.5,.5])+',42%,56%)';x.fillRect(0,0,W,14);
  /* 레이더 */
  var CX=W/2,CY=430,R=195;
  function pt(i,v){var a=-Math.PI/2+i*Math.PI/3;return [CX+Math.cos(a)*R*v,CY+Math.sin(a)*R*v]}
  function path(vals){x.beginPath();vals.forEach(function(v,i){var p=pt(i,Math.max(.05,v));
    i?x.lineTo(p[0],p[1]):x.moveTo(p[0],p[1])});x.closePath()}
  x.strokeStyle=hair;x.lineWidth=1.5;
  [.25,.5,.75,1].forEach(function(r){path([r,r,r,r,r,r]);x.stroke()});
  for(var i=0;i<6;i++){var p=pt(i,1);x.beginPath();x.moveTo(CX,CY);x.lineTo(p[0],p[1]);x.stroke()}
  if(s.f){x.setLineDash([7,7]);x.strokeStyle=ink2;x.lineWidth=2.5;path(s.f);x.stroke();x.setLineDash([])}
  var mine=log?log.mine:(s.f||[.5,.5,.5,.5,.5,.5]);
  x.fillStyle=dark?'rgba(201,168,106,.22)':'rgba(31,111,74,.2)';
  x.strokeStyle=dark?'#c9a86a':'#1f6f4a';x.lineWidth=5;path(mine);x.fill();x.stroke();
  /* 축 라벨 */
  x.fillStyle=ink2;x.textAlign='center';
  var AXJ=['華やか','芳醇','重厚','穏やか','ドライ','軽快'];
  AXJ.forEach(function(t,i){var p=pt(i,1.2);
    x.font='30px "Yu Mincho","Hiragino Mincho ProN",serif';x.fillText(t,p[0],p[1]+10);
    x.font='20px system-ui';x.fillStyle=dark?'#8c8375':'#9a9284';
    x.fillText(AX[i][1],p[0],p[1]+38);x.fillStyle=ink2});
  /* 이름 — 일본어 이름 옆에 한국어 독음을 붙인다. 이미지는 앱 밖으로 나가는 결과물이라
     한자만 남으면 읽을 수가 없다. 제품명이 이미 독음으로 시작하면 겹치므로 생략한다. */
  var cat=catOf(id), yomi=(cat&&cat.ko)||'';
  if(yomi&&(s.ko||'').indexOf(yomi)===0)yomi='';
  x.textAlign='center';x.fillStyle=ink;
  x.font='96px "Yu Mincho","Hiragino Mincho ProN",serif';
  if(yomi){
    var wJp=x.measureText(s.jp).width;
    x.font='30px system-ui,sans-serif';
    var wKo=x.measureText(yomi).width, gap=18, left=(W-(wJp+gap+wKo))/2;
    x.textAlign='left';
    x.font='96px "Yu Mincho","Hiragino Mincho ProN",serif';
    x.fillText(s.jp,left,870);
    x.font='30px system-ui,sans-serif';x.fillStyle=ink2;
    x.fillText(yomi,left+wJp+gap,870);
    x.textAlign='center';
  }else{
    x.fillText(s.jp,W/2,870);
  }
  /* 제품명은 길다("아라마사 No.6 X-type 나마 720ml"). 한 줄로 자르면 정보가 날아가므로
     폭에 맞춰 두 줄까지 접는다. */
  x.font='30px system-ui,sans-serif';x.fillStyle=ink2;
  wrapText(x,(s.ko||s.brewery||''),W/2,920,W-200,38,2);
  /* 한 줄 */
  if(log&&log.memo){
    x.font='italic 34px system-ui,sans-serif';x.fillStyle=ink;
    var m=log.memo.length>30?log.memo.slice(0,30)+'…':log.memo;
    x.fillText('\u201c'+m+'\u201d',W/2,1000);
  }
  /* 태그·온도 */
  if(log){
    /* 이미지는 밖으로 나가는 결과물이라 한국어로 적는다(앱 화면은 일본어 병기) */
    var line=[];
    if(typeof log.temp==='number')line.push(TEMPS[log.temp][1]);
    (log.tags||[]).slice(0,4).forEach(function(t){line.push(tagKo(t))});
    if(line.length){x.font='28px system-ui,sans-serif';x.fillStyle=ink2;
      x.fillText(line.join('  \u00b7  '),W/2,1068)}
  }
  /* 하단 */
  x.strokeStyle=hair;x.lineWidth=1.5;x.beginPath();x.moveTo(90,1170);x.lineTo(W-90,1170);x.stroke();
  x.font='24px ui-monospace,Menlo,monospace';x.textAlign='left';x.fillStyle=ink2;
  x.fillText((s.area||'').toString(),90,1218);
  x.textAlign='right';x.fillText('SAKE CARD',W-90,1218);
  x.textAlign='center';x.font='20px system-ui';x.fillStyle=dark?'#7d7466':'#9a9284';
  x.fillText('\u3055\u3051\u306e\u308f\u30c7\u30fc\u30bf\u3092\u52a0\u5de5\u3057\u3066\u5229\u7528', W/2, 1290);

  c.toBlob(function(b){
    var a=document.createElement('a');a.href=URL.createObjectURL(b);
    a.download='sake_'+((s.jp||'card')+(s.ko?'_'+s.ko:''))
      .replace(/[\\/:*?"<>|]/g,'').slice(0,60)+'.png';a.click();
    toast('이미지를 저장했습니다');
  },'image/png');
}
function closeSheet(){$('#sheet').classList.remove('on');curId=null}

/* ── 탭 ── */
function go(name){
  $$('.pane').forEach(function(p){p.classList.toggle('on',p.id==='p-'+name)});
  $$('.nav button').forEach(function(b){b.classList.toggle('on',b.dataset.go===name)});
  var T={home:['사케 카드','마신 사케를 카드로 모으고, 맛을 6축으로 그려 기록합니다.'],
         dex:['도감','사케를 찾아 「마셨어요」를 누르면 내 카드가 됩니다.'],
         mine:['내 카드','담은 카드입니다. 카드를 열면 테이스팅 노트를 쓸 수 있습니다.'],
         stat:['분석','담은 카드로 내 취향을 읽습니다.'],
         me:['기록','저장과 백업.']};
  $('#ttl').textContent=T[name][0]; $('#sub').textContent=T[name][1];
  window.scrollTo(0,0);
  if(name==='home')renderHome(); if(name==='dex')renderDex(); if(name==='mine')renderMine();
  if(name==='stat')renderStats();
  if(name==='me')renderMe();
  try{localStorage.setItem('sake.tab',name)}catch(e){}
}
window.go=go;
function renderMe(){
  var m=Object.keys(MINE).length,n=Object.keys(NOTE).reduce(function(a,k){return a+logsOf(k).length},0);
  $('#me-sum').innerHTML='카드 <b>'+m+'종</b> · 테이스팅 노트 <b>'+n+'건</b>'
    +(m?'<br>가장 최근 담은 카드: '+esc((mineList()[0]||{}).jp||'-'):'');
}
/* 내 취향 — 내가 그린 6축의 평균. 도감 평균과 겹쳐 "나는 무엇을 더 세게 느끼나"를 본다.
   노트가 적을 때 단정하지 않도록 건수를 함께 보여준다. */
function renderTaste(total){
  var box=$('#me-taste'); if(!box)return;
  if(!total){box.innerHTML='<h3>내 취향</h3><p>테이스팅 노트를 쓰면 여기에 <b>내가 느낀 맛의 평균</b>이 그려집니다.<br>'
    +'도감 평균과 겹쳐 보여 어떤 맛을 강하게 느끼는지 드러납니다.</p>';return}
  var sum=[0,0,0,0,0,0], ref=[0,0,0,0,0,0], cnt=0, refN=0;
  var tagCnt={}, tempCnt={}, againCnt=[0,0,0];
  Object.keys(NOTE).forEach(function(id){
    var s=catOf(id);
    logsOf(id).forEach(function(l){
      if(!l.mine)return;
      l.mine.forEach(function(v,i){sum[i]+=v}); cnt++;
      (l.tags||[]).forEach(function(t){tagCnt[t]=(tagCnt[t]||0)+1});
      if(typeof l.temp==='number')tempCnt[l.temp]=(tempCnt[l.temp]||0)+1;
      if(typeof l.again==='number')againCnt[l.again]++;
    });
    if(s&&s.f){s.f.forEach(function(v,i){ref[i]+=v});refN++}
  });
  if(!cnt){box.innerHTML='<h3>내 취향</h3><p>아직 그린 값이 없습니다.</p>';return}
  var avg=sum.map(function(v){return v/cnt});
  var refAvg=refN?ref.map(function(v){return v/refN}):null;
  var gaps=[];
  if(refAvg)avg.forEach(function(v,i){var g=v-refAvg[i];
    if(Math.abs(g)>.1)gaps.push([AX[i][1],g])});
  gaps.sort(function(a,b){return Math.abs(b[1])-Math.abs(a[1])});
  var topTags=Object.keys(tagCnt).sort(function(a,b){return tagCnt[b]-tagCnt[a]}).slice(0,5);
  var topTemp=Object.keys(tempCnt).sort(function(a,b){return tempCnt[b]-tempCnt[a]})[0];
  var again=againCnt[0], agTot=againCnt[0]+againCnt[1]+againCnt[2];
  box.innerHTML='<h3>내 취향 <span style="font-weight:400;color:var(--ink3)">노트 '+cnt+'건 기준</span></h3>'
    +radarSVG(avg, refAvg)
    +'<p class="legend">'+(refAvg?'<span style="color:var(--ink3)">— — 도감 평균</span> &nbsp; ':'')
    +'<span style="color:var(--me)">—— 내가 그린 평균</span></p>'
    +(gaps.length?'<p class="diff">도감 평균보다 <b>'+gaps.slice(0,2).map(function(g){
        return g[0]+(g[1]>0?'을 강하게':'을 약하게')}).join('</b>, <b>')+'</b> 느끼는 편입니다.</p>'
      :'<p class="diff">도감 평균과 비슷하게 느끼는 편입니다.</p>')
    +(cnt<5?'<p class="diff" style="font-size:11.5px;color:var(--ink3)">기록이 '+cnt+'건이라 아직 경향이라 부르긴 이릅니다.</p>':'')
    +(topTags.length?'<div class="sec"><h3>자주 고른 맛·향</h3><div class="chips">'
      +topTags.map(function(t){var ko=(TAGS.find(function(x){return x[0]===t})||[])[1]||'';
        return '<div class="chip on"><b style="font-family:var(--disp)">'+esc(t)+'</b> <span style="opacity:.7;font-size:10px">'+esc(ko)+' '+tagCnt[t]+'</span></div>'}).join('')
      +'</div></div>':'')
    +(topTemp!==undefined?'<div class="sec"><h3>가장 많이 마신 온도</h3><p class="diff"><b>'
      +TEMPS[topTemp][0]+'</b> '+TEMPS[topTemp][1]+' · '+tempCnt[topTemp]+'회</p></div>':'')
    +(agTot?'<div class="sec"><h3>또 마신다</h3><p class="diff"><b>'+again+'</b> / '+agTot+'건 ('
      +Math.round(again/agTot*100)+'%)</p></div>':'');
}
function refresh(){renderHome();renderDex();renderMine();renderStats();renderMe()}

/* ── 시작 ── */
fetch('./catalog.json',{cache:'no-cache'}).then(function(r){return r.json()}).then(function(d){
  CAT=d.items; MINE=load(K_MINE,{}); NOTE=load(K_NOTE,{});
  $('#dex-chips').innerHTML=[['all','전체'],['new','안 마신 것'],['mine','담은 것']]
    .map(function(c,i){return '<div class="chip'+(i===0?' on':'')+'" data-dexf="'+c[0]+'">'+c[1]+'</div>'}).join('');
  $('#mine-chips').innerHTML=[['all','전체'],['noted','노트 쓴 것'],['blank','아직 안 쓴 것']]
    .map(function(c,i){return '<div class="chip'+(i===0?' on':'')+'" data-minef="'+c[0]+'">'+c[1]+'</div>'}).join('');
  $('#build').textContent='build '+(d.v||1)+' · 도감 '+CAT.length+'종';
  refresh();
  var t=null; try{t=localStorage.getItem('sake.tab')}catch(e){}
  go(t&&['home','dex','mine','stat','me'].indexOf(t)>=0?t:'home');
}).catch(function(){ $('#home-recent').innerHTML='<p class="diff">도감을 불러오지 못했습니다.</p>' });

document.addEventListener('click',function(e){
  var nav=e.target.closest('.nav button'); if(nav){go(nav.dataset.go);return}
  var c=e.target.closest('.c'); if(c){openSheet(c.dataset.id);return}
  var df=e.target.closest('[data-dexf]');
  if(df){dexFilter=df.dataset.dexf;$$('[data-dexf]').forEach(function(x){x.classList.toggle('on',x===df)});dexN=60;renderDex();return}
  var mf=e.target.closest('[data-minef]');
  if(mf){mineFilter=mf.dataset.minef;$$('[data-minef]').forEach(function(x){x.classList.toggle('on',x===mf)});renderMine();return}
  if(e.target.id==='dex-more'){dexN+=60;renderDex();return}
  if(e.target.id==='a-manual'){openManual();return}
  if(e.target.id==='go-blank'){var b=nextBlank(null); if(b)openSheet(b); return}
  var ar=e.target.closest('[data-area]');
  if(ar){go('dex');var q=$('#q');q.value=ar.dataset.area;
    q.dispatchEvent(new Event('input',{bubbles:true}));return}
  if(e.target.id==='sheet'){closeSheet();return}
});
document.addEventListener('input',function(e){
  if(e.target.id==='q'){dexN=60;renderDex()}
  if(e.target.id==='mq')renderMine();
});
document.addEventListener('change',function(e){
  if(e.target.id==='sort')renderDex();
  if(e.target.id==='msort')renderMine();
});
document.addEventListener('keydown',function(e){if(e.key==='Escape')closeSheet()});

/* 내보내기 · 가져오기 */
document.addEventListener('click',function(e){
  if(e.target.id==='exp'){
    var blob=new Blob([JSON.stringify({v:1,exported_at:new Date().toISOString(),
      mine:MINE,notes:NOTE},null,1)],{type:'application/json'});
    var a=document.createElement('a');a.href=URL.createObjectURL(blob);
    a.download='sake_my_record.json';a.click();toast('내보냈습니다');
  }
  if(e.target.id==='imp')$('#file').click();
});
document.addEventListener('change',function(e){
  if(e.target.id!=='file'||!e.target.files[0])return;
  var fr=new FileReader();
  fr.onload=function(){
    try{
      var d=JSON.parse(fr.result);
      if(d.mine){Object.keys(d.mine).forEach(function(k){MINE[k]=d.mine[k]})}
      if(d.notes){Object.keys(d.notes).forEach(function(k){NOTE[k]=d.notes[k]})}
      /* 내보낸 컬렉션 파일(items 배열) 도 받는다.
         brand 가 빈 항목은 도감에 없는 술이다 — 버리지 않고 own: id 로 담는다
         (2026-09-16: 135종 중 9종이 이렇게 통째로 유실되고 있었다). */
      if(d.items){
        d.items.forEach(function(it){
          var prod=(it.name||'').trim(), jp=(it.jp||'').trim(), key;
          if(it.brand){
            key=prod?it.brand+'#'+prod:it.brand;
          }else{
            /* 도감에 없는 술. jp 가 비어 제품명만 오는 경우가 있어(실측 8건)
               괄호 앞 토막을 이름으로 세운다. */
            var label=jp||prod; if(!label)return;
            if(!jp)jp=prod.split(/[ (（·]/)[0].trim()||prod;
            key='own:'+label.replace(/[^\w가-힣ぁ-んァ-ン一-龯]/g,'').slice(0,24);
            if(prod&&prod!==jp)key+='#'+prod;
          }
          /* 같은 병이 두 번 오면 먼저 마신 날짜를 남긴다 */
          var at=it.at||'', old=MINE[key];
          if(old&&old.at&&(!at||old.at<at))at=old.at;
          MINE[key]={at:at,jp:jp||'?',name:prod};
        });
      }
      save(K_MINE,MINE);save(K_NOTE,NOTE);refresh();
      toast('가져왔습니다 — 카드 '+Object.keys(MINE).length+'종');
    }catch(err){toast('파일을 읽지 못했습니다')}
  };
  fr.readAsText(e.target.files[0]);
});
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(function(){});

/* 설치 안내 — 아직 홈 화면에 추가하지 않은 경우에만. 한 번 닫으면 다시 뜨지 않는다.
   아이폰 사파리는 설치 API 가 없어 손으로 하는 법을 적고, 안드로이드 크롬은
   beforeinstallprompt 를 잡아 버튼 한 번으로 끝낸다(안내만 띄우면 아무도 안 한다). */
(function(){
  var iOS=/iPad|iPhone|iPod/.test(navigator.userAgent)&&!window.MSStream;
  var standalone=window.navigator.standalone===true||
    (window.matchMedia&&window.matchMedia('(display-mode: standalone)').matches);
  var dismissed=false; try{dismissed=localStorage.getItem('sake.install.hide')==='1'}catch(e){}
  var box=document.getElementById('install'), deferred=null;
  function show(){if(box&&!standalone&&!dismissed)box.hidden=false}
  if(iOS)show();
  window.addEventListener('beforeinstallprompt',function(e){
    e.preventDefault(); deferred=e;
    var how=document.getElementById('i-how'), add=document.getElementById('i-add');
    if(how)how.textContent='버튼 한 번이면 끝납니다. 주소창 없이 전체화면으로 뜨고, 비행기에서도 열립니다.';
    if(add)add.hidden=false;
    show();
  });
  window.addEventListener('appinstalled',function(){
    if(box)box.hidden=true;
    try{localStorage.setItem('sake.install.hide','1')}catch(err){}
  });
  document.addEventListener('click',function(e){
    if(e.target.id==='i-add'&&deferred){
      deferred.prompt(); deferred=null;
      if(box)box.hidden=true;
      return;
    }
    if(e.target.id==='i-close'){
      if(box)box.hidden=true;
      try{localStorage.setItem('sake.install.hide','1')}catch(err){}
    }
  });
})();
})();
